import{_ as o,c as a,o as s,ah as r,ao as i,ap as t}from"./chunks/framework.Dq2_gudl.js";const v=JSON.parse('{"title":"Permissão Para Sofrer — Deus Guarda Suas Lágrimas num Vaso","description":"Chorar por um pet não é falta de fé. Os Salmos dizem que Deus recolhe nossas lágrimas num vaso e as registra no Seu livro.","frontmatter":{"title":"Permissão Para Sofrer — Deus Guarda Suas Lágrimas num Vaso","description":"Chorar por um pet não é falta de fé. Os Salmos dizem que Deus recolhe nossas lágrimas num vaso e as registra no Seu livro."},"headers":[],"relativePath":"pt/pets-in-heaven/permission-to-grieve.md","filePath":"pt/pets-in-heaven/permission-to-grieve.md"}'),n={name:"pt/pets-in-heaven/permission-to-grieve.md"};function p(m,e,u,l,c,d){return s(),a("div",null,[...e[0]||(e[0]=[r('<div class="pl-quote"><p>“Já faz meses e eu ainda choro. Será que não sou forte o bastante? Será que minha fé é pequena?”</p><p class="pl-quote-soft">A Bíblia nunca trata lágrimas como prova de fracasso. Muito pelo contrário.</p></div><section class="pl-section"><h2>1. Deus guarda lágrimas num vaso</h2><blockquote><p><strong>Salmos 56:8</strong></p><p>&quot;Thou tellest my wanderings: put thou my tears into thy bottle: are they not in thy book?&quot;</p></blockquote><p>Davi escreveu isso em meio a um sofrimento profundo. Ele pede que Deus guarde suas lágrimas num vaso e as registre num livro — no mundo antigo, um vaso de lágrimas era uma coleção preciosa, a prova de que “esta pessoa chorou por isto”.</p><p>O que significa: <strong>suas lágrimas não são algo que cai e desaparece.</strong> Nem uma gota é desperdiçada. Cada lágrima que você derramou por ele é recolhida. É registrada.</p><p>Então, quando você pensar “será que estou chorando demais?” — lembre-se: para Deus aquilo não é ruído. É um registro.</p></section><section class="pl-section"><h2>2. Deus se aproxima dos quebrantados — Ele não os repreende</h2><blockquote><p><strong>Salmos 34:18</strong></p><p>&quot;The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit.&quot;</p></blockquote><blockquote><p><strong>Salmos 147:3</strong></p><p>&quot;He healeth the broken in heart, and bindeth up their wounds.&quot;</p></blockquote><p>Repare nos verbos: Ele <em>se aproxima</em>. Ele <em>cura</em>. Ele <em>enfaixa</em>. A primeira coisa que Deus faz pelos que sofrem não é exigir que se recomponham — é caminhar até eles.</p><p>Jesus também disse uma frase curta:</p><blockquote><p><strong>Mateus 5:4</strong></p><p>&quot;Blessed are they that mourn: for they shall be comforted.&quot;</p></blockquote><p>“Bem-aventurados os que choram.” Os que sofrem não são repreendidos — são declarados bem-aventurados, porque o consolo vem. Não é “você deveria ficar animado”, mas “você será consolado”.</p></section><section class="pl-section"><h2>3. O luto não é o oposto do amor — é o amor continuando</h2><p>Não choramos pelo que nunca amamos. A razão de doer tanto é que realmente houve amor entre vocês.</p><p>Deus nos fez seres que choram pelas perdas. O próprio Jesus chorou no túmulo de Lázaro (João 11:35) — sabendo que em minutos o ressuscitaria, Ele ainda chorou.</p><p>Então você não deve desculpas a ninguém pelas suas lágrimas. Você não está com pouca fé. Você está simplesmente ferido no amor.</p><p class="pl-quote-soft">Se quiser, você pode orar assim:</p></section><div class="pl-quote"><p>“Senhor, Tu sabes quantas vezes eu chorei.<br>Obrigado por não me apressar a ficar bem, e por guardar cada lágrima no Teu vaso.<br>Aproxima-Te de mim, como Te aproximas de todo coração quebrantado;<br>cura-me, e por favor cuida daquele que eu amo e perdi.<br>Hoje eu não quero ser forte. Só quero ser abraçado por Ti. Amém.”</p></div><section class="pl-section"><h2>Quatro coisas que você pode fazer por si agora</h2><div class="pl-moment-grid"><div class="pl-moment"><span class="pl-moment-icon">🌊</span><h3>Não decida nada no auge</h3><p>As ondas do luto passam. No pior momento, tudo o que você precisa é sobreviver aos próximos cinco minutos. Não resolva mais nada.</p></div><div class="pl-moment"><span class="pl-moment-icon">🍽️</span><h3>Cuide do corpo primeiro</h3><p>Beba água. Coma algo. Durma. O luto consome o corpo, e um corpo com fome faz o coração doer mais.</p></div><div class="pl-moment"><span class="pl-moment-icon">📝</span><h3>Escreva sobre ele num caderno</h3><p>Não precisa ser bonito. Escreva um detalhe: como ele te acordava, sua expressão favorita dele. Dê à saudade um lugar para ficar.</p></div><div class="pl-moment"><span class="pl-moment-icon">🤝</span><h3>Encontre alguém que realmente entenda</h3><p>Nem todos entendem chorar por um animal, mas alguns entendem. Se não encontrar, escreva — Deus consegue ler.</p></div></div></section><section class="pl-section"><h2>Aquele dia vai chegar</h2><p>O Apocalipse promete que um dia o próprio Deus enxugará toda lágrima dos nossos olhos, e não haverá mais morte, nem tristeza, nem choro, nem dor (Apocalipse 21:4). Naquele dia você descobrirá que cada lágrima que derramou por ele foi lembrada e respondida por um Deus bom.</p><p>Até lá — dê a si mesmo permissão para sofrer. É mais uma forma de ainda amá-lo.</p><p><a href="/pt/pets-in-heaven/">← Voltar para Pets in Heaven</a> ｜ Primeira leitura: <a href="/pt/pets-in-heaven/will-i-see-my-pet-again">Vou Ver Meu Pet de Novo?</a></p></section><div class="pl-cta"><h2>Hoje, uma frase já basta.</h2><p>O PetLoss inclui um diário guiado e um companheiro SOS que oferece palavras de ancoragem nos momentos mais pesados. Sem conta, sem uploads, totalmente offline.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">Baixar na App Store</a></div><div class="pl-bible"><h3>Deixe a Palavra de Deus continuar com você</h3><p>Todos os versículos deste artigo vêm da Bíblia. Com o Rainbow Bible, você pode ler as Escrituras a qualquer momento e criar um widget de versículo diário — uma pequena luz nos dias em que sente saudade.</p><div class="pl-bible-shots"><figure><img src="'+i+'" alt="Widget do Rainbow Bible exibindo 2 Timóteo 2:13" loading="lazy"><figcaption>Versículo diário na tela inicial</figcaption></figure><figure><img src="'+t+'" alt="App Rainbow Bible — tema Pets no Céu exibindo Mateus 10:29-31" loading="lazy"><figcaption>Leia a Palavra no tema Pets no Céu</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">Baixar o Rainbow Bible na App Store</a></div>',9)])])}const g=o(n,[["render",p]]);export{v as __pageData,g as default};
